using Godot;
using System;
public partial class ActorSpatialGizmoOperations
{
    public void draw(Node owner)
    {
        var lens=camera(owner);if(!enabled(owner)||lens==null)return;var gizmo=Gizmo(owner);var fog=Module(owner,"fog_paint");if(fog.Call("active").AsBool()){fog.Call("draw");return;}var damage=Module(owner,"damage");var structure=Module(owner,"structure");damage.Call("draw");structure.Call("draw");if(structure.Call("active").AsBool()||damage.Call("active").AsBool())return;var pins=Module(owner,"physics_pins");if(pins.Call("active").AsBool()){pins.Call("draw");return;}var model=Model(owner);
        foreach(var value in model.Get("clips").AsGodotArray()){var clip=value.As<Resource>();var runtime=Runtime(owner,clip);if(runtime==null||!runtime.Get("active").AsBool()||Ui(runtime))continue;if(model.Call("is_selected",clip.Get("id")).AsBool()){if(Script(runtime,"physics/powder/powder_runtime"))GD.Load<GDScript>("res://scripts/actors/physics/powder/powder_gizmo.gd").Call("draw",owner,runtime);var color=new Color(clip.Get("id").AsString()==model.Get("selected_id").AsString()?"ffd078":"80bdff");foreach(var line in box_lines(owner,runtime)){var points=line.AsVector2Array();gizmo.DrawLine(points[0],points[1],new Color(0,0,0,.65f),4,true);gizmo.DrawLine(points[0],points[1],color,1.6f,true);}}else if(Proxies.Contains(Actor(runtime).Get("type_id").AsString())&&!lens.IsPositionBehind(Remote(runtime).Origin)){var point=project(owner,Remote(runtime).Origin);gizmo.DrawLine(point-new Vector2(5,0),point+new Vector2(5,0),new Color("8dacc0"),2,true);gizmo.DrawLine(point-new Vector2(0,5),point+new Vector2(0,5),new Color("8dacc0"),2,true);}}
        var data=geometry(owner);var rig=Module(owner,"rig");if(data.Count==0){rig.Call("draw");return;}string mode=Mode(owner);for(int i=0;i<3;i++){var rect=toolbar_rect(i);bool selected=mode==Modes[i];gizmo.DrawRect(rect,new Color(selected?"285c57":"152430"));gizmo.DrawRect(rect,new Color(selected?"71d8be":"456172"),false,1);gizmo.DrawString(ThemeDB.FallbackFont,rect.Position+new Vector2(6,18),new[]{"Move  W","Rotate  E","Scale  R"}[i],HorizontalAlignment.Left,66,11,new Color("e3f1f3"));}
        var center=data["center"].AsVector2();var ends=data["ends"].AsVector2Array();for(int i=0;i<3;i++){var color=Colors3[i];if(mode=="rotate")gizmo.DrawPolyline(data["rings"].AsGodotArray()[i].AsVector2Array(),color,2.5f,true);else{var end=ends[i];if(center.DistanceTo(end)<14)continue;gizmo.DrawLine(center,end,new Color("10212d"),5,true);gizmo.DrawLine(center,end,color,2.5f,true);if(mode=="scale")gizmo.DrawRect(new Rect2(end-new Vector2(5,5),new Vector2(10,10)),color);else{var direction=(end-center).Normalized();var side=direction.Orthogonal();gizmo.DrawColoredPolygon(new[]{end+direction*4,end-direction*10+side*5,end-direction*10-side*5},color);}gizmo.DrawString(ThemeDB.FallbackFont,end+new Vector2(7,-5),new[]{"X","Y","Z"}[i],HorizontalAlignment.Left,14,12,color);}}if(mode!="rotate")gizmo.DrawRect(new Rect2(center-new Vector2(5,5),new Vector2(10,10)),new Color("f6db9a"));if(owner.Get("before").AsGodotArray().Count>0)gizmo.DrawString(ThemeDB.FallbackFont,new Vector2(12,57),"Ctrl: snap  ·  Esc: cancel",HorizontalAlignment.Left,-1,11,new Color("f6db9a"));rig.Call("draw");
    }
}
